flow.set('TIME_MS', msg.TIME_MS);
flow.set('LEVEL_THRESHOLD', msg.LEVEL_THRESHOLD);
flow.set('DEBOUNCE_MS', msg.DEBOUNCE_MS);
flow.set('lastWarn', 0);
return null;

const level = Number(msg.payload.level);
if (isNaN(level)) { return null; }

flow.set('wl_a', { level, ts: Date.now() });

return compareAndWarn();

function compareAndWarn() {
    const a = flow.get('wl_a');
    const b = flow.get('wl_b');
    if (!a || !b) return null;

    const timeTol = flow.get('TIME_MS') || 5000;
    if (Math.abs(a.ts - b.ts) > timeTol) return null;

    const threshold = flow.get('LEVEL_THRESHOLD') || 50;
    const diff = Math.abs(a.level - b.level);
    if (diff < threshold) return null;

    const debounce = flow.get('DEBOUNCE_MS') || 30000;
    const last = flow.get('lastWarn') || 0;
    if (Date.now() - last < debounce) return null;
    flow.set('lastWarn', Date.now());

    return { payload: { warning: true, diff, a: a.level, b: b.level, ts: new Date().toISOString() } };
}

